var https = require('https');

// ── Config ────────────────────────────────────────────────────────────────
var SUPABASE_URL = 'https://pddktbfaaltxvlxcfoaq.supabase.co';
var SUPABASE_KEY = $vars.SUPABASE_SERVICE_KEY;
var GRAPH       = 'https://graph.facebook.com/v21.0';
var sbHeaders   = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY };

// ── Helpers HTTP ──────────────────────────────────────────────────────────
function parseJson(str) {
  try { return JSON.parse(str); } catch(e) { return {}; }
}

function parseHost(urlStr) {
  var s = urlStr.replace('https://', '');
  var idx = s.indexOf('/');
  return { host: idx === -1 ? s : s.substring(0, idx),
           path: idx === -1 ? '/' : s.substring(idx) };
}

function httpsGet(urlStr, headers) {
  return new Promise(function(resolve, reject) {
    var u = parseHost(urlStr);
    var req = https.request(
      { hostname: u.host, path: u.path, method: 'GET', headers: headers || {} },
      function(res) {
        var data = '';
        res.on('data', function(c) { data += c; });
        res.on('end',  function()  { resolve(parseJson(data)); });
      }
    );
    req.on('error', reject);
    req.end();
  });
}

function httpsPatch(urlStr, body, headers) {
  return new Promise(function(resolve, reject) {
    var bodyStr = JSON.stringify(body);
    var u = parseHost(urlStr);
    var allHeaders = Object.assign(
      { 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      headers || {}
    );
    var req = https.request(
      { hostname: u.host, path: u.path, method: 'PATCH', headers: allHeaders },
      function(res) {
        var data = '';
        res.on('data', function(c) { data += c; });
        res.on('end',  function()  { resolve(data); });
      }
    );
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

function toFormBody(obj) {
  var parts = [];
  var keys = Object.keys(obj);
  for (var i = 0; i < keys.length; i++) {
    var k = keys[i]; var v = obj[k];
    if (v !== undefined && v !== null) {
      parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(v)));
    }
  }
  return parts.join('&');
}

function postForm(urlStr, params) {
  return new Promise(function(resolve, reject) {
    var body = toFormBody(params);
    var u = parseHost(urlStr);
    var req = https.request(
      { hostname: u.host, path: u.path, method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' } },
      function(res) {
        var data = '';
        res.on('data', function(c) { data += c; });
        res.on('end',  function()  { resolve(parseJson(data)); });
      }
    );
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function igCreateAndPublish(igId, containerParams, pageToken) {
  var containerResp = await postForm(GRAPH + '/' + igId + '/media', containerParams);
  if (containerResp.error) return { post_id: null, error: containerResp.error.message };
  if (!containerResp.id)   return { post_id: null, error: 'Instagram nao retornou creation_id' };
  var publishResp = await postForm(GRAPH + '/' + igId + '/media_publish', {
    creation_id: containerResp.id, access_token: pageToken,
  });
  return {
    post_id: publishResp.id || containerResp.id,
    error: publishResp.error ? publishResp.error.message : null,
  };
}

// ── Horário Brasília (UTC-3) ───────────────────────────────────────────────
var utcNow = new Date();
var brasilia = new Date(utcNow.getTime() - 3 * 60 * 60 * 1000);
var year  = brasilia.getFullYear();
var month = String(brasilia.getMonth() + 1).padStart(2, '0');
var day   = String(brasilia.getDate()).padStart(2, '0');
var hours = String(brasilia.getHours()).padStart(2, '0');
var mins  = String(brasilia.getMinutes()).padStart(2, '0');
var today       = year + '-' + month + '-' + day;
var currentTime = hours + ':' + mins;

// ── Buscar conteúdos aprovados com data <= hoje ───────────────────────────
var contentsUrl = SUPABASE_URL + '/rest/v1/contents' +
  '?select=id,client_id,type,caption,generated_image_url,media_urls,scheduled_date,scheduled_time' +
  '&status=eq.approved_by_client' +
  '&scheduled_date=lte.' + today;

var contents = await httpsGet(contentsUrl, sbHeaders);
if (!Array.isArray(contents)) contents = [];

// ── Filtrar prontos (hora chegou) ─────────────────────────────────────────
var ready = [];
for (var i = 0; i < contents.length; i++) {
  var c = contents[i];
  var cTime = c.scheduled_time || '09:00';
  if (c.scheduled_date < today || (c.scheduled_date === today && cTime <= currentTime)) {
    ready.push(c);
  }
}

if (ready.length === 0) {
  return [{ json: { published: 0, message: 'Nenhum conteudo para publicar agora (' + today + ' ' + currentTime + ')' } }];
}

// ── Publicar cada conteúdo ────────────────────────────────────────────────
var results = [];

for (var j = 0; j < ready.length; j++) {
  var content = ready[j];
  var result  = { content_id: content.id, facebook: null, instagram: null, error: null };

  try {
    // Buscar cliente
    var clientsResp = await httpsGet(
      SUPABASE_URL + '/rest/v1/clients?select=facebook_page_id,facebook_page_token,instagram_account_id&id=eq.' + content.client_id,
      sbHeaders
    );
    var client = Array.isArray(clientsResp) && clientsResp.length > 0 ? clientsResp[0] : null;

    if (!client || !client.facebook_page_id || !client.facebook_page_token) {
      result.error = 'Cliente sem integracoes Meta configuradas';
      results.push(result);
      continue;
    }

    // Buscar Page Token real
    var tokenResp = await httpsGet(
      GRAPH + '/' + client.facebook_page_id + '?fields=access_token&access_token=' + client.facebook_page_token,
      {}
    );
    var pageToken = tokenResp.access_token || client.facebook_page_token;

    var type    = content.type || 'imagem';
    var isStory = type === 'story';
    var imgUrl  = (type === 'carrossel' && content.media_urls && content.media_urls.length)
                  ? content.media_urls[0] : content.generated_image_url;

    // ── Facebook ──────────────────────────────────────────────────────────
    var fbPostId = null, fbError = null;
    try {
      var fbParams = {}, fbResp = {};

      if (isStory && content.generated_image_url) {
        fbResp   = await postForm(GRAPH + '/' + client.facebook_page_id + '/photo_stories',
                     { url: content.generated_image_url, access_token: pageToken });
        fbPostId = fbResp.post_id || fbResp.id || null;
        fbError  = fbResp.error ? fbResp.error.message : null;

      } else if (type === 'reel' && content.generated_image_url) {
        fbParams = { file_url: content.generated_image_url, published: 'true', access_token: pageToken };
        if (content.caption) fbParams.description = content.caption;
        fbResp   = await postForm(GRAPH + '/' + client.facebook_page_id + '/videos', fbParams);
        fbPostId = fbResp.id || null;
        fbError  = fbResp.error ? fbResp.error.message : null;

      } else {
        var fbEndpoint = imgUrl
          ? GRAPH + '/' + client.facebook_page_id + '/photos'
          : GRAPH + '/' + client.facebook_page_id + '/feed';
        fbParams = { published: 'true', access_token: pageToken };
        if (imgUrl) { fbParams.url = imgUrl; fbParams.caption = content.caption || ''; }
        else        { fbParams.message = content.caption || ''; }
        fbResp   = await postForm(fbEndpoint, fbParams);
        fbPostId = fbResp.id || null;
        fbError  = fbResp.error ? fbResp.error.message : null;
      }
    } catch(e) { fbError = String(e.message); }

    result.facebook = { post_id: fbPostId, error: fbError };

    // ── Instagram ─────────────────────────────────────────────────────────
    var igPostId = null, igError = null;

    if (client.instagram_account_id) {
      try {
        var igParams = {}, igResult = {};

        if (type === 'carrossel' && content.media_urls && content.media_urls.length >= 2) {
          var itemIds = [];
          for (var k = 0; k < content.media_urls.length; k++) {
            var itemResp = await postForm(GRAPH + '/' + client.instagram_account_id + '/media',
              { image_url: content.media_urls[k], is_carousel_item: 'true', access_token: pageToken });
            if (itemResp.error) { igError = itemResp.error.message; break; }
            if (itemResp.id)    itemIds.push(itemResp.id);
          }
          if (!igError && itemIds.length >= 2) {
            igResult = await igCreateAndPublish(client.instagram_account_id, {
              media_type: 'CAROUSEL', children: itemIds.join(','),
              caption: content.caption || '', access_token: pageToken,
            }, pageToken);
            igPostId = igResult.post_id; igError = igResult.error;
          }

        } else if (type === 'reel' && content.generated_image_url) {
          igResult = await igCreateAndPublish(client.instagram_account_id, {
            media_type: 'REELS', video_url: content.generated_image_url,
            caption: content.caption || '', access_token: pageToken,
          }, pageToken);
          igPostId = igResult.post_id; igError = igResult.error;

        } else if (isStory && content.generated_image_url) {
          igResult = await igCreateAndPublish(client.instagram_account_id, {
            media_type: 'STORIES', image_url: content.generated_image_url,
            access_token: pageToken,
          }, pageToken);
          igPostId = igResult.post_id; igError = igResult.error;

        } else if (content.generated_image_url) {
          igResult = await igCreateAndPublish(client.instagram_account_id, {
            image_url: content.generated_image_url,
            caption: content.caption || '', access_token: pageToken,
          }, pageToken);
          igPostId = igResult.post_id; igError = igResult.error;
        }
      } catch(e) { igError = String(e.message); }
    }

    result.instagram = { post_id: igPostId, error: igError };

    // ── Atualizar Supabase ────────────────────────────────────────────────
    var updateData = { status: 'published' };
    if (fbPostId) updateData.facebook_post_id  = fbPostId;
    if (igPostId) updateData.instagram_post_id = igPostId;

    await httpsPatch(
      SUPABASE_URL + '/rest/v1/contents?id=eq.' + content.id,
      updateData,
      sbHeaders
    );

  } catch(e) {
    result.error = String(e.message);
  }

  results.push(result);
}

return [{ json: { published: results.length, brasilia_time: today + ' ' + currentTime, results: results } }];
